fn test_matmul(allocator: Allocator) !void {
    const shape_a = &.{2, 3};
    var a = try Tensor.init(allocator, shape_a, .f64);
    defer a.deinit();
    try a.set(f64, &.{0,0}, 1); try a.set(f64, &.{0,1}, 2); try a.set(f64, &.{0,2}, 3);
    try a.set(f64, &.{1,0}, 4); try a.set(f64, &.{1,1}, 5); try a.set(f64, &.{1,2}, 6);

    const shape_b = &.{3, 4};
    var b = try Tensor.init(allocator, shape_b, .f64);
    defer b.deinit();
    try b.set(f64, &.{0,0}, 7);  try b.set(f64, &.{0,1}, 8);  try b.set(f64, &.{0,2}, 9);  try b.set(f64, &.{0,3}, 10);
    try b.set(f64, &.{1,0}, 11); try b.set(f64, &.{1,1}, 12); try b.set(f64, &.{1,2}, 13); try b.set(f64, &.{1,3}, 14);
    try b.set(f64, &.{2,0}, 15); try b.set(f64, &.{2,1}, 16); try b.set(f64, &.{2,2}, 17); try b.set(f64, &.{2,3}, 18);

