fn test_backward(allocator: Allocator) !void {
    const shape = &.{1};
    var tensor = try Tensor.init(allocator, shape, .f64);
    defer tensor.deinit();
    tensor.requires_grad = true;

    var grad_out1 = try Tensor.init(allocator, shape, .f64);
    defer grad_out1.deinit();
    try grad_out1.set(f64, &.{0}, 1.0);

    try tensor.backward(grad_out1);
    if (tensor.grad) |g| {
        try testing.expectEqual(@as(f64, 1.0), try g.get(f64, &.{0}));
    } else {
        return error.InvalidShapeForOp;
    }

    var grad_out2 = try Tensor.init(allocator, shape, .f64);
    defer grad_out2.deinit();
    try grad_out2.set(f64, &.{0}, 2.5);

    try tensor.backward(grad_out2);
    if (tensor.grad) |g| {
        try testing.expectEqual(@as(f64, 3.5), try g.get(f64, &.{0}));
    }
}

