rec pluscommutative : {M:nat} {N:nat} {P:nat}
  plus M N P -> plus N M P -> type.
= mlam M mlam N mlam P fn d =>
  case M of
  z => let {g:plus z N N} g = plusz d in g
  (s M) => let {g:plus (s M) N (s P)} {D:plus M N P} g = pluss D d in
    let {g:plus N M P} g = D pluscommutative M N P in
    {g:plus N (s M) (s P)} pluss g.

rec plusassociative : {M:nat} {N:nat} {K:nat} {P:nat} {Q:nat} {R:nat}
  plus M N P -> plus P K R -> plus N K Q -> plus M Q R -> type.
= mlam M mlam N mlam K mlam P mlam Q mlam R fn d1 fn d2 fn d3 =>
  case M of
  z => let {g:plus z N N} g = plusz d1 in d2
  (s M) => let {g:plus (s M) N (s P)} {D1:plus M N P} g = pluss D1 d1 in
    let {g:plus (s P) K (s R)} {D2:plus P K R} g = pluss D2 d2 in
    let {g:plus M Q R} {D:plus N K Q} D = D plusassociative M N K P Q R in
    {g:plus (s M) Q (s R)} pluss D.

rec plusdeterministic : {M:nat} {N:nat} {P1:nat} {P2:nat}
  plus M N P1 -> plus M N P2 -> P1 = P2 -> type.
= mlam M mlam N mlam P1 mlam P2 fn d1 fn d2 =>
  case d1 of
  plusz => case d2 of
    plusz => refl
  pluss D1 => case d2 of
    pluss D2 => let {g:P1 = P2} refl = plusdeterministic N D1 D2 in refl.

rec multcommutative : {M:nat} {N:nat} {P:nat}
  mult M N P -> mult N M P -> type.
= mlam M mlam N mlam P fn d =>
  case M of
  z => let {g:mult z N z} g = multz d in multz
  (s M) => let {g:mult (s M) N P} {D1:mult M N _} {D2:plus N _ P} g = mults D1 D2 d in
    let {g:mult N M _} g = D1 multcommutative M N _ in
    {g:mult N (s M) P} mults g D2.

rec multdistributive : {M:nat} {N:nat} {K:nat} {P:nat} {Q:nat} {R:nat}
  mult M N P -> mult M K Q -> plus N K R -> mult M R (plus P Q) -> type.
= mlam M mlam N mlam K mlam P mlam Q mlam R fn d1 fn d2 fn d3 =>
  case M of
  z => let {g:mult z N z} g = multz d1 in let {g:mult z K z} g = multz d2 in multz
  (s M) => let {g:mult (s M) N P} {D1:mult M N _} {D2:plus N _ P} g = mults D1 D2 d1 in
    let {g:mult (s M) K Q} {D3:mult M K _} {D4:plus K _ Q} g = mults D3 D4 d2 in
    let {g:mult M R _} {D:plus N K R} D = D multdistributive M N K _ _ R in
    {g:mult (s M) R (plus P Q)} mults D (pluss D2).

rec multdeterministic : {M:nat} {N:nat} {P1:nat} {P2:nat}
  mult M N P1 -> mult M N P2 -> P1 = P2 -> type.
= mlam M mlam N mlam P1 mlam P2 fn d1 fn d2 =>
  case d1 of
  multz => case d2 of
    multz => refl
  mults D1 D2 => case d2 of
    mults D3 D4 => let {g:P1 = P2} refl = multdeterministic N D1 D3 in refl.

rec leqreflexive : {N:nat} leq N N -> type.
= mlam N =>
  case N of
  z => leqz
  (s N) => let {g:leq N N} g = D leqreflexive N in {g:leq (s N) (s N)} leqs g.

rec leqtransitive : {M:nat} {N:nat} {K:nat}
  leq M N -> leq N K -> leq M K -> type.
= mlam M mlam N mlam K fn d1 fn d2 =>
  case M of
  z => leqz
  (s M) => case N of
    (s N) => case K of
      (s K) => let {g:leq M N} {D1:leq M N} g = leqs D1 d1 in
        let {g:leq (s N) (s K)} {D2:leq N K} g = leqs D2 d2 in
        let {g:leq M K} {D:leq M K} D = D leqtransitive M N K D1 D2 in
        {g:leq (s M) (s K)} leqs D.

rec leqantisymmetric : {M:nat} {N:nat}
  leq M N -> leq N M -> M = N -> type.
= mlam M mlam N fn d1 fn d2 =>
  case M of
  z => case N of
    z => refl
  (s M) => case N of
    (s N) => let {g:leq M N} {D1:leq M N} g = leqs D1 d1 in
      let {g:leq N M} {D2:leq N M} g = leqs D2 d2 in
      let {g:M = N} refl = leqantisymmetric M N D1 D2 in
      refl.

rec ltirreflexive : {N:nat} (lt N N -> bool) -> type.
= mlam N fn d =>
  case d of
  ltbase => bfalse
  ltstep D => ltirreflexive N D.

rec lttransitive : {M:nat} {N:nat} {K:nat}
  lt M N -> lt N K -> lt M K -> type.
= mlam M mlam N mlam K fn d1 fn d2 =>
  case d2 of
  ltbase => {g:lt M (s N)} ltstep d1
  ltstep D => let {g:lt M K} {D:lt M K} D = D lttransitive M N K d1 D in {g:lt M (s K)} ltstep D.

rec ltdeterministicwitness : {M:nat} {N1:nat} {N2:nat}
  lt M N1 -> lt M N2 -> leq N1 N2 -> type.
= mlam M mlam N1 mlam N2 fn d1 fn d2 =>
  case d1 of
  ltbase => case d2 of
    ltbase => leqreflexive M
    ltstep D => {g:leq (s M) (s N2)} leqs leqz
  ltstep D1 => case d2 of
    ltbase => leqz
    ltstep D2 => let {g:leq N1 N2} {D:leq N1 N2} D = D ltdeterministicwitness M N1 N2 D1 D2 in {g:leq (s N1) (s N2)} leqs D.

rec totalelementspositive : {S:shape} {N:nat}
  totalelements S N -> leq (s z) N -> type.
= mlam S mlam N fn d =>
  case d of
  tenil => leqs leqz
  tecons D1 D2 => leqs leqz.

rec totalelementsunique : {S:shape} {N1:nat} {N2:nat}
  totalelements S N1 -> totalelements S N2 -> N1 = N2 -> type.
= mlam S mlam N1 mlam N2 fn d1 fn d2 =>
  case d1 of
  tenil => case d2 of
    tenil => refl
  tecons D1 D2 => case d2 of
    tecons D3 D4 => let {g:N1 = N2} refl = totalelementsunique S D1 D3 in
      let {g:_ = _} refl = multdeterministic _ D2 D4 in
      refl.

rec stridespecunique : {S:shape} {P:nat} {St1:nat} {St2:nat}
  stridespec S P St1 -> stridespec S P St2 -> St1 = St2 -> type.
= mlam S mlam P mlam St1 mlam St2 fn d1 fn d2 =>
  case d1 of
  sslast => case d2 of
    sslast => refl
  sscons D1 D2 => case d2 of
    sscons D3 D4 => let {g:St1 = St2} refl = stridespecunique _ _ _ _ D1 D3 in
      let {g:_ = _} refl = multdeterministic _ D2 D4 in
      refl.

rec shapelenunique : {S:shape} {N1:nat} {N2:nat}
  shapelen S N1 -> shapelen S N2 -> N1 = N2 -> type.
= mlam S mlam N1 mlam N2 fn d1 fn d2 =>
  case d1 of
  slnil => case d2 of
    slnil => refl
  slcons D1 => case d2 of
    slcons D2 => let {g:N1 = N2} refl = shapelenunique _ _ _ D1 D2 in refl.

rec flatindexdeterministic : {IL:indexlist N} {Shp:shape} {Strides:shape} {Off:nat} {R1:nat} {R2:nat}
  flatindexcalc IL Shp Strides Off R1 -> flatindexcalc IL Shp Strides Off R2 -> R1 = R2 -> type.
= mlam IL mlam Shp mlam Strides mlam Off mlam R1 mlam R2 fn d1 fn d2 =>
  case d1 of
  ficnil => case d2 of
    ficnil => refl
  ficcons D1 D2 D3 => case d2 of
    ficcons D4 D5 D6 => let {g:R1 = R2} refl = multdeterministic _ D1 D4 in
      let {g:_ = _} refl = plusdeterministic _ D2 D5 in
      flatindexdeterministic _ _ _ _ _ _ D3 D6.

rec tensorgetinbounds : {IL:indexlist Len} {S:shape} {Strides:shape} {Off:nat} {Idx:nat} {Total:nat}
  indexinbounds IL S -> flatindexcalc IL S Strides Off Idx -> totalelements S Total -> lt Idx Total -> type.
= mlam IL mlam S mlam Strides mlam Off mlam Idx mlam Total fn d1 fn d2 fn d3 =>
  case d1 of
  iibnil => case d2 of
    ficnil => case d3 of
      tenil => ltbase
  iibcons D1 D2 => case d2 of
    ficcons D3 D4 D5 => ltbase.

