= mlam B mlam C mlam IH mlam IW mlam OH mlam OW mlam KS mlam St mlam N1 mlam N2 fn d1 fn d2 =>
  totalelementsunique _ N1 N2 d1 d2.

rec batchnormdeterministic : {BS:nat} {CH:nat} {N1:nat} {N2:nat}
  totalelements (shapecons BS (shapecons CH shapenil)) N1 -> totalelements (shapecons BS (shapecons CH shapenil)) N2 -> N1 = N2 -> type.
= mlam BS mlam CH mlam N1 mlam N2 fn d1 fn d2 =>
  totalelementsunique _ N1 N2 d1 d2.

rec layernormdeterministic : {S:shape} {N1:nat} {N2:nat}
