rec embeddingdeterministic : {V:nat} {E:nat} {N:nat} {T1:nat} {T2:nat}
  totalelements (shapecons N (shapecons E shapenil)) T1 -> totalelements (shapecons N (shapecons E shapenil)) T2 -> T1 = T2 -> type.
= mlam V mlam E mlam N mlam T1 mlam T2 fn d1 fn d2 =>
