rec dropoutdeterministicwithseed : {S:shape} {N1:nat} {N2:nat} {Seed:nat}
  totalelements S N1 -> totalelements S N2 -> N1 = N2 -> type.
= mlam S mlam N1 mlam N2 mlam Seed fn d1 fn d2 =>
