rec spectralnormdeterministic : {S:shape} {Iters:nat} {N1:nat} {N2:nat}
  totalelements S N1 -> totalelements S N2 -> spectralnormconvergence Iters -> N1 = N2 -> type.
= mlam S mlam Iters mlam N1 mlam N2 fn d1 fn d2 fn d3 =>
  totalelementsunique S N1 N2 d1 d2.

rec savedeterministic : {S:shape} {N1:nat} {N2:nat}
  fileiospec S N1 -> fileiospec S N2 -> N1 = N2 -> type.
= mlam S mlam N1 mlam N2 fn d1 fn d2 =>
  case d1 of
  fios D1 => case d2 of
    fios D2 => totalelementsunique S N1 N2 D1 D2
